from pathlib import Path
import base64
ROOT = Path('shdk-personnel-app-v0.6.0')

(ROOT / 'package.json').parent.mkdir(parents=True, exist_ok=True)
(ROOT / 'package.json').write_bytes(base64.b64decode(''))
(ROOT / 'src/storage/SqliteStorageAdapter.ts').parent.mkdir(parents=True, exist_ok=True)
(ROOT / 'src/storage/SqliteStorageAdapter.ts').write_bytes(base64.b64decode(''))
(ROOT / 'src/main/main.ts').parent.mkdir(parents=True, exist_ok=True)
(ROOT / 'src/main/main.ts').write_bytes(base64.b64decode(''))
(ROOT / 'src/main/ipc.ts').parent.mkdir(parents=True, exist_ok=True)
(ROOT / 'src/main/ipc.ts').write_bytes(base64.b64decode(' '))
(ROOT / 'src/storage/migrations.ts').parent.mkdir(parents=True, exist_ok=True)
(ROOT / 'src/storage/migrations.ts').write_bytes(base64.b64decode(''))
(ROOT / 'tests/sqliteStorage.test.ts').parent.mkdir(parents=True, exist_ok=True)
(ROOT / 'tests/sqliteStorage.test.ts').write_bytes(base64.b64decode(''))
for rel in ['src/storage/RocksDbStorageAdapter.ts','src/storage/rocksdb.d.ts','src/storage/keys.ts']:
    (ROOT / rel).unlink(missing_ok=True)
app = ROOT / 'src/renderer/App.tsx'
text = app.read_text(encoding='utf-8')
text = text.replace("RocksDB · {dbPath ? 'подключена' : '...'}", "SQLite · {dbPath ? 'подключена' : '...'}")
text = text.replace('Дерево подразделений из RocksDB.', 'Дерево подразделений из SQLite.')
text = text.replace('commitText="Записать в RocksDB"', 'commitText="Записать в SQLite"')
app.write_text(text, encoding='utf-8')
print('Patched SHDK v0.7.0 to SQLite/sql.js storage')
